document.addEventListener("DOMContentLoaded",function(){document.getElementById("form").addEventListener("submit",function(e){e.preventDefault();var e=document.getElementById("nome").value,t=document.getElementById("tel").value.replace(/\D/g,"");11===t.length?(t=`(${t.substring(0,2)}) ${t.substring(2,7)}-`+t.substring(7),document.getElementById("name").innerText=e,document.getElementById("phone").innerText=t):alert("Número Inválido. Por favor, insira o DDD e o número completo com 11 dígitos.")})});